"""Apply Quantum Trader v3.5.45 on top of v3.5.44: a live bot trade keeps its
stop, T1/T2/T3, locked floor and peak across a restart + adopt_position."""
import base64, hashlib, os, py_compile, sys, zlib
ITEMS = [{'f': 'backend/app/state.py', 'old': '2d499320214ec2273ae2eb4b946f9c7e782f6c6a6bb79f3e2282b3fe90651dca', 'new': ''}, {'f': 'backend/_smoke_v3545.py', 'old': None, 'new': ''}]
bad = []
for it in ITEMS:
    p = it["f"]
    new = zlib.decompress(base64.b64decode(it["new"]))
    if not os.path.exists(p):
        if it["old"] is not None:
            bad.append(p + " (missing)")
        continue
    h = hashlib.sha256(open(p, "rb").read().replace(b"\r\n", b"\n")).hexdigest()
    if h == hashlib.sha256(new).hexdigest():
        if it["old"] is None:
            continue
        print("already v3.5.45:", p); sys.exit(1)
    if it["old"] is not None and h != it["old"]:
        bad.append(p)
if bad:
    print("REFUSED - not the v3.5.44 version (apply qt_v3543 then qt_v3544 first):", bad); sys.exit(1)
for it in ITEMS:
    p = it["f"]
    if os.path.exists(p) and not os.path.exists(p + ".pre3545.bak"):
        os.replace(p, p + ".pre3545.bak")
    open(p, "wb").write(zlib.decompress(base64.b64decode(it["new"])))
    if p.endswith(".py"):
        py_compile.compile(p, doraise=True)
print("v3.5.45 applied OK (backups: *.pre3545.bak)")
